parameters.query:
update dead_letters set replay_requested_at = now()
where id = $1::bigint and replayed_at is null
returning id as dead_letter_id, application_id, 'replay' as source;

update dead_letters set replayed_at = now(), replay_outcome = $2
where id = $1::bigint
returning id, application_id, replay_outcome;

